# Dot-sourced by verify_supabase_contract.ps1; catalog checks only.
$shareGoodOperations = @(
  @{ Public = 'create_share_good_invite_v1'; Private = 'share_good_create_invite_v1'; Types = 'jsonb,text,text,text,text,text'; Args = 'p_target jsonb, p_moment text, p_mode text, p_identity_mode text, p_visible_name text, p_timezone text'; Anon = $false },
  @{ Public = 'create_share_good_chain_invite_v1'; Private = 'share_good_create_chain_invite_v1'; Types = 'text,text,jsonb,text,text,text,text,text'; Args = 'p_parent_token text, p_participant_key text, p_target jsonb, p_moment text, p_mode text, p_identity_mode text, p_visible_name text, p_timezone text'; Anon = $false },
  @{ Public = 'resolve_share_good_invite_v1'; Private = 'share_good_resolve_invite_v1'; Types = 'text,text'; Args = 'p_token text, p_participant_key text'; Anon = $true },
  @{ Public = 'advance_share_good_participation_v1'; Private = 'share_good_advance_participation_v1'; Types = 'text,text,text'; Args = 'p_token text, p_participant_key text, p_status text'; Anon = $true },
  @{ Public = 'disclose_share_good_completion_v1'; Private = 'share_good_disclose_completion_v1'; Types = 'text,text,text'; Args = 'p_token text, p_participant_key text, p_visible_name text'; Anon = $false },
  @{ Public = 'get_share_good_impact_v1'; Private = 'share_good_get_impact_v1'; Types = ''; Args = ''; Anon = $false }
)
foreach ($operation in $shareGoodOperations) {
  $anon = if ($operation.Anon) { 'true' } else { 'false' }
  foreach ($schema in @('public', 'private')) {
    $name = if ($schema -eq 'public') { $operation.Public } else { $operation.Private }
    $signature = "$schema.$name($($operation.Types))"
    $definer = if ($schema -eq 'private') { 'true' } else { 'false' }
    Check "share good function $signature" "SELECT p.prosecdef=$definer AND p.proconfig=ARRAY['search_path=' || chr(34) || chr(34)]::text[] AND pg_get_function_result(p.oid)='jsonb' AND pg_get_function_arguments(p.oid)='$($operation.Args)' AND has_function_privilege('authenticated',p.oid,'EXECUTE') AND has_function_privilege('anon',p.oid,'EXECUTE')=$anon AND NOT has_function_privilege('service_role',p.oid,'EXECUTE') AND NOT EXISTS (SELECT 1 FROM aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a WHERE a.grantee=0 AND a.privilege_type='EXECUTE') FROM pg_proc p WHERE p.oid='$signature'::regprocedure"
  }
}
foreach ($table in @('share_good_invites','share_good_invite_identities','share_good_participations','share_good_completion_disclosures','share_good_rate_limits')) {
  Check "share good RLS $table" "SELECT relrowsecurity FROM pg_class WHERE oid='public.$table'::regclass"
  Check "share good table ACL $table" "SELECT NOT has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') AND NOT has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') AND NOT has_table_privilege('service_role',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') AND NOT has_any_column_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,REFERENCES') AND NOT has_any_column_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,REFERENCES') AND NOT has_any_column_privilege('service_role',c.oid,'SELECT,INSERT,UPDATE,REFERENCES') AND NOT EXISTS (SELECT 1 FROM aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) a WHERE a.grantee=0) AND NOT EXISTS (SELECT 1 FROM pg_attribute x, LATERAL aclexplode(x.attacl) a WHERE x.attrelid=c.oid AND a.grantee=0) FROM pg_class c WHERE c.oid='public.$table'::regclass"
}
Check 'share good internal helpers closed' "SELECT NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='private' AND p.proname LIKE 'share_good_%' AND (NOT p.prosecdef OR p.proconfig IS DISTINCT FROM ARRAY['search_path=' || chr(34) || chr(34)]::text[] OR has_function_privilege('service_role',p.oid,'EXECUTE') OR EXISTS (SELECT 1 FROM aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a WHERE a.grantee=0 AND a.privilege_type='EXECUTE') OR (p.proname NOT IN ('share_good_create_invite_v1','share_good_create_chain_invite_v1','share_good_resolve_invite_v1','share_good_advance_participation_v1','share_good_disclose_completion_v1','share_good_get_impact_v1') AND (has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('authenticated',p.oid,'EXECUTE'))) OR (p.proname NOT IN ('share_good_resolve_invite_v1','share_good_advance_participation_v1') AND has_function_privilege('anon',p.oid,'EXECUTE'))))"
Check 'share good extra public RPCs closed' "SELECT NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE '%share_good%_v1' AND (p.proname NOT IN ('create_share_good_invite_v1','create_share_good_chain_invite_v1','resolve_share_good_invite_v1','advance_share_good_participation_v1','disclose_share_good_completion_v1','get_share_good_impact_v1') OR (p.proname NOT IN ('resolve_share_good_invite_v1','advance_share_good_participation_v1') AND has_function_privilege('anon',p.oid,'EXECUTE'))))"
$allowedPublic = ($shareGoodOperations | ForEach-Object { "'public.$($_.Public)($($_.Types))'::regprocedure" }) -join ','
$allowedPrivate = ($shareGoodOperations | ForEach-Object { "'private.$($_.Private)($($_.Types))'::regprocedure" }) -join ','
$allowedAnonPrivate = ($shareGoodOperations | Where-Object { $_.Anon } | ForEach-Object { "'private.$($_.Private)($($_.Types))'::regprocedure" }) -join ','
Check 'share good private schema guest access is exact' "SELECT has_schema_privilege('anon','private','USAGE') AND NOT has_schema_privilege('anon','private','CREATE') AND NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='private' AND p.oid NOT IN ($allowedAnonPrivate) AND has_function_privilege('anon',p.oid,'EXECUTE'))"
Check 'share good unexpected overloads closed' "SELECT NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname='public' AND p.proname LIKE '%share_good%_v1' AND p.oid NOT IN ($allowedPublic)) OR (n.nspname='private' AND p.proname LIKE 'share_good_%' AND ((p.oid NOT IN ($allowedPrivate) AND has_function_privilege('authenticated',p.oid,'EXECUTE')) OR (p.oid NOT IN ($allowedAnonPrivate) AND has_function_privilege('anon',p.oid,'EXECUTE')))))"
Check 'share good deletion foreign keys' "SELECT (SELECT count(*)=1 FROM pg_constraint WHERE contype='f' AND conrelid='public.share_good_invites'::regclass AND confrelid='auth.users'::regclass AND confdeltype='n') AND (SELECT count(*)=2 FROM pg_constraint WHERE contype='f' AND conrelid IN ('public.share_good_invite_identities'::regclass,'public.share_good_completion_disclosures'::regclass) AND confrelid='auth.users'::regclass AND confdeltype='c') AND (SELECT count(*)=2 FROM pg_constraint WHERE contype='f' AND ((conrelid='public.share_good_invite_identities'::regclass AND confrelid='public.share_good_invites'::regclass) OR (conrelid='public.share_good_completion_disclosures'::regclass AND confrelid='public.share_good_participations'::regclass)) AND confdeltype='c')"
Check 'share good uniqueness indexes' "SELECT EXISTS (SELECT 1 FROM pg_index i WHERE i.indrelid='public.share_good_invites'::regclass AND i.indisunique AND pg_get_indexdef(i.indexrelid) LIKE '%(token_hash)%') AND EXISTS (SELECT 1 FROM pg_index i WHERE i.indrelid='public.share_good_participations'::regclass AND i.indisunique AND pg_get_indexdef(i.indexrelid) LIKE '%(invite_id, participant_key_hash)%') AND EXISTS (SELECT 1 FROM pg_index i WHERE i.indrelid='public.share_good_rate_limits'::regclass AND i.indisprimary AND pg_get_indexdef(i.indexrelid) LIKE '%(scope_hash, action, window_start)%')"
